SELECT CASE WHEN o.status IN ('CANCELLED', 'RETURNED') THEN 'core' ELSE 'other' END AS status_group, MONTH(o.order_date) AS order_month, SUM(p.amount) AS total_amount, MAX(p.amount) - MIN(p.amount) AS amount_range FROM payments p LEFT JOIN orders o ON p.order_id = o.id LEFT JOIN customers c ON o.customer_id = c.id WHERE p.method = 'card' GROUP BY CASE WHEN o.status IN ('CANCELLED', 'RETURNED') THEN 'core' ELSE 'other' END, MONTH(o.order_date)
